UPDATE `markets` SET `consumption_en` = '$180M/year', `consumption_es` = '180 M$/año', `consumption_de` = '180 Mio. $/Jahr', `consumption_zh` = '每年 180 百万美元', `consumption_ar` = '180 مليون دولار/سنة', `cigars_en` = '~18M premium cigars/year', `cigars_es` = '~18 M de puros premium/año', `cigars_de` = 'ca. 18 Mio. Premium-Zigarren/Jahr', `cigars_zh` = '每年约 18 百万支优质雪茄', `cigars_ar` = '~18 مليون سيجار فاخر/سنة', `trend_en` = 'stable', `trend_es` = 'estable', `trend_de` = 'stabil', `trend_zh` = '平稳', `trend_ar` = 'مستقر', `note_en` = 'Legal access to Cuban Habanos, unlike the United States. A sophisticated market with a large community of connoisseurs.', `note_es` = 'Acceso legal a los Habanos cubanos, a diferencia de EE. UU. Mercado sofisticado, con una gran comunidad de conocedores.', `note_de` = 'Legaler Zugang zu kubanischen Habanos, anders als in den USA. Anspruchsvoller Markt mit einer großen Kennergemeinde.', `note_zh` = '与美国不同，可合法购得古巴哈瓦那雪茄。市场成熟，鉴赏者众多。', `note_ar` = 'وصول قانوني إلى الهابانوس الكوبية، بخلاف الولايات المتحدة. سوق متطوّرة بمجتمع كبير من الخبراء.' WHERE `id` = 'canada_mkt';
UPDATE `markets` SET `consumption_en` = '$1.2B/year', `consumption_es` = '1.2 B$/año', `consumption_de` = '1.2 Mrd. $/Jahr', `consumption_zh` = '每年 1.2 十亿美元', `consumption_ar` = '1.2 مليار دولار/سنة', `cigars_en` = '~120M premium cigars/year', `cigars_es` = '~120 M de puros premium/año', `cigars_de` = 'ca. 120 Mio. Premium-Zigarren/Jahr', `cigars_zh` = '每年约 120 百万支优质雪茄', `cigars_ar` = '~120 مليون سيجار فاخر/سنة', `trend_en` = 'strong growth', `trend_es` = 'fuerte crecimiento', `trend_de` = 'starkes Wachstum', `trend_zh` = '强劲增长', `trend_ar` = 'نمو قوي', `note_en` = 'A booming market where the Cuban cigar is a status symbol. Dubai and Hong Kong serve as Asian distribution hubs.', `note_es` = 'Mercado en plena expansión, donde el puro cubano es un símbolo de estatus. Dubái y Hong Kong son los centros de distribución asiáticos.', `note_de` = 'Boomender Markt, in dem die kubanische Zigarre ein Statussymbol ist. Dubai und Hongkong sind die asiatischen Vertriebsdrehscheiben.', `note_zh` = '市场迅猛增长，古巴雪茄是身份象征。迪拜与香港为亚洲分销枢纽。', `note_ar` = 'سوق مزدهرة يمثّل فيها السيجار الكوبي رمزًا للمكانة. دبي وهونغ كونغ مركزا التوزيع الآسيوي.' WHERE `id` = 'china_mkt';
UPDATE `markets` SET `consumption_en` = '$2.1B/year', `consumption_es` = '2.1 B$/año', `consumption_de` = '2.1 Mrd. $/Jahr', `consumption_zh` = '每年 2.1 十亿美元', `consumption_ar` = '2.1 مليار دولار/سنة', `cigars_en` = '~280M cigars/year', `cigars_es` = '~280 M de puros/año', `cigars_de` = 'ca. 280 Mio. Zigarren/Jahr', `cigars_zh` = '每年约 280 百万支雪茄', `cigars_ar` = '~280 مليون سيجار/سنة', `trend_en` = 'growth', `trend_es` = 'crecimiento', `trend_de` = 'Wachstum', `trend_zh` = '增长', `trend_ar` = 'نمو', `note_en` = 'The only market where Cuban Habanos are freely sold. France, Germany, Switzerland and Spain lead, on a strong cigar culture.', `note_es` = 'El único mercado donde los Habanos cubanos se venden libremente. Francia, Alemania, Suiza y España a la cabeza, con una fuerte cultura del puro.', `note_de` = 'Der einzige Markt, auf dem kubanische Habanos frei verkauft werden. Frankreich, Deutschland, die Schweiz und Spanien führen, mit ausgeprägter Zigarrenkultur.', `note_zh` = '唯一可自由销售古巴哈瓦那雪茄的市场。以法国、德国、瑞士、西班牙为首，雪茄文化深厚。', `note_ar` = 'السوق الوحيدة التي تُباع فيها الهابانوس الكوبية بحرية. تتصدّرها فرنسا وألمانيا وسويسرا وإسبانيا، بثقافة سيجار راسخة.' WHERE `id` = 'eu_mkt';
UPDATE `markets` SET `consumption_en` = '$160M/year', `consumption_es` = '160 M$/año', `consumption_de` = '160 Mio. $/Jahr', `consumption_zh` = '每年 160 百万美元', `consumption_ar` = '160 مليون دولار/سنة', `cigars_en` = '~15M premium cigars/year', `cigars_es` = '~15 M de puros premium/año', `cigars_de` = 'ca. 15 Mio. Premium-Zigarren/Jahr', `cigars_zh` = '每年约 15 百万支优质雪茄', `cigars_ar` = '~15 مليون سيجار فاخر/سنة', `trend_en` = 'stable', `trend_es` = 'estable', `trend_de` = 'stabil', `trend_zh` = '平稳', `trend_ar` = 'مستقر', `note_en` = 'Altadis (Seita) is the exclusive Habanos distributor in France. A strong Parisian cigar-bar culture, constrained by the Évin Act.', `note_es` = 'Altadis (Seita) es el distribuidor exclusivo de Habanos en Francia. Fuerte cultura de bares de puros en París, limitada por la ley Évin.', `note_de` = 'Altadis (Seita) ist exklusiver Habanos-Vertrieb in Frankreich. Ausgeprägte Pariser Zigarrenbar-Kultur, eingeschränkt durch das Évin-Gesetz.', `note_zh` = 'Altadis（Seita）为哈瓦那雪茄在法国的独家经销商。巴黎雪茄吧文化浓厚，但受《埃万法》限制。', `note_ar` = 'ألتاديس (سيتا) الموزّع الحصري للهابانوس في فرنسا. ثقافة قوية لبارات السيجار في باريس، يقيّدها قانون إيفان.' WHERE `id` = 'france_mkt';
UPDATE `markets` SET `consumption_en` = '$380M/year', `consumption_es` = '380 M$/año', `consumption_de` = '380 Mio. $/Jahr', `consumption_zh` = '每年 380 百万美元', `consumption_ar` = '380 مليون دولار/سنة', `cigars_en` = '~40M premium cigars/year', `cigars_es` = '~40 M de puros premium/año', `cigars_de` = 'ca. 40 Mio. Premium-Zigarren/Jahr', `cigars_zh` = '每年约 40 百万支优质雪茄', `cigars_ar` = '~40 مليون سيجار فاخر/سنة', `trend_en` = 'stable', `trend_es` = 'estable', `trend_de` = 'stabil', `trend_zh` = '平稳', `trend_ar` = 'مستقر', `note_en` = 'A highly developed cigar culture. Habanos Japan is the official distributor, with a network of premium cellars in the major cities.', `note_es` = 'Cultura del puro muy desarrollada. Habanos Japan es el distribuidor oficial, con una red de bodegas premium en las grandes ciudades.', `note_de` = 'Hoch entwickelte Zigarrenkultur. Habanos Japan ist offizieller Vertrieb, mit einem Netz von Premium-Kellern in den Großstädten.', `note_zh` = '雪茄文化高度发达。Habanos Japan 为官方经销商，各大城市设有高端雪茄窖网络。', `note_ar` = 'ثقافة سيجار متطوّرة جدًا. هابانوس اليابان هو الموزّع الرسمي، مع شبكة أقبية فاخرة في المدن الكبرى.' WHERE `id` = 'japan_mkt';
UPDATE `markets` SET `consumption_en` = '$220M/year', `consumption_es` = '220 M$/año', `consumption_de` = '220 Mio. $/Jahr', `consumption_zh` = '每年 220 百万美元', `consumption_ar` = '220 مليون دولار/سنة', `cigars_en` = '~22M premium cigars/year', `cigars_es` = '~22 M de puros premium/año', `cigars_de` = 'ca. 22 Mio. Premium-Zigarren/Jahr', `cigars_zh` = '每年约 22 百万支优质雪茄', `cigars_ar` = '~22 مليون سيجار فاخر/سنة', `trend_en` = 'decline (sanctions)', `trend_es` = 'declive (sanciones)', `trend_de` = 'Rückgang (Sanktionen)', `trend_zh` = '下滑（制裁）', `trend_ar` = 'تراجع (عقوبات)', `note_en` = 'A traditional market in decline since 2022. Historically strong demand for Cuban cigars, now redistributed through parallel channels.', `note_es` = 'Mercado tradicional en retroceso desde 2022. Demanda cubana históricamente fuerte, redistribuida por canales paralelos.', `note_de` = 'Traditioneller Markt, seit 2022 rückläufig. Historisch starke Nachfrage nach kubanischen Zigarren, heute über Parallelkanäle verteilt.', `note_zh` = '传统市场自 2022 年起萎缩。对古巴雪茄的需求历来强劲，现通过平行渠道流通。', `note_ar` = 'سوق تقليدية تتراجع منذ 2022. طلب كوبي قوي تاريخيًا، يُعاد توزيعه عبر قنوات موازية.' WHERE `id` = 'russia_mkt';
UPDATE `markets` SET `consumption_en` = '$140M/year', `consumption_es` = '140 M$/año', `consumption_de` = '140 Mio. $/Jahr', `consumption_zh` = '每年 140 百万美元', `consumption_ar` = '140 مليون دولار/سنة', `cigars_en` = '~14M premium cigars/year', `cigars_es` = '~14 M de puros premium/año', `cigars_de` = 'ca. 14 Mio. Premium-Zigarren/Jahr', `cigars_zh` = '每年约 14 百万支优质雪茄', `cigars_ar` = '~14 مليون سيجار فاخر/سنة', `trend_en` = 'growth', `trend_es` = 'crecimiento', `trend_de` = 'Wachstum', `trend_zh` = '增长', `trend_ar` = 'نمو', `note_en` = 'Davidoff\'s world headquarters are in Geneva; Intertabak AG distributes Habanos. Watchmaking and cigar traditions are closely entwined.', `note_es` = 'La sede mundial de Davidoff está en Ginebra; Intertabak AG distribuye Habanos. Relojería y puro son tradiciones estrechamente ligadas.', `note_de` = 'Davidoffs Weltzentrale liegt in Genf; Intertabak AG vertreibt Habanos. Uhrmacher- und Zigarrentradition sind eng verwoben.', `note_zh` = '大卫杜夫全球总部设于日内瓦，Intertabak AG 经销哈瓦那雪茄。制表与雪茄传统紧密相连。', `note_ar` = 'المقر العالمي لدافيدوف في جنيف، وإنترتاباك AG توزّع الهابانوس. تقاليد صناعة الساعات والسيجار متشابكة.' WHERE `id` = 'switz_mkt';
UPDATE `markets` SET `consumption_en` = '$290M/year', `consumption_es` = '290 M$/año', `consumption_de` = '290 Mio. $/Jahr', `consumption_zh` = '每年 290 百万美元', `consumption_ar` = '290 مليون دولار/سنة', `cigars_en` = '~30M premium cigars/year', `cigars_es` = '~30 M de puros premium/año', `cigars_de` = 'ca. 30 Mio. Premium-Zigarren/Jahr', `cigars_zh` = '每年约 30 百万支优质雪茄', `cigars_ar` = '~30 مليون سيجار فاخر/سنة', `trend_en` = 'strong growth', `trend_es` = 'fuerte crecimiento', `trend_de` = 'starkes Wachstum', `trend_zh` = '强劲增长', `trend_ar` = 'نمو قوي', `note_en` = 'Dubai is a global hub for luxury transit and consumption. An ultra-premium international clientele, growing 15% a year.', `note_es` = 'Dubái es un centro mundial de tránsito y consumo de lujo. Clientela internacional ultrapremium, con un crecimiento del 15 % anual.', `note_de` = 'Dubai ist eine globale Drehscheibe für Luxus-Transit und -Konsum. Ultra-Premium-Klientel, jährliches Wachstum von 15 %.', `note_zh` = '迪拜是奢侈品中转与消费的全球枢纽。国际顶级客群，年增长 15%。', `note_ar` = 'دبي مركز عالمي لعبور واستهلاك الكماليات. عملاء دوليون من الفئة الفاخرة، بنمو 15٪ سنويًا.' WHERE `id` = 'uae_mkt';
UPDATE `markets` SET `consumption_en` = '$260M/year', `consumption_es` = '260 M$/año', `consumption_de` = '260 Mio. $/Jahr', `consumption_zh` = '每年 260 百万美元', `consumption_ar` = '260 مليون دولار/سنة', `cigars_en` = '~28M premium cigars/year', `cigars_es` = '~28 M de puros premium/año', `cigars_de` = 'ca. 28 Mio. Premium-Zigarren/Jahr', `cigars_zh` = '每年约 28 百万支优质雪茄', `cigars_ar` = '~28 مليون سيجار فاخر/سنة', `trend_en` = 'stable', `trend_es` = 'estable', `trend_de` = 'stabil', `trend_zh` = '平稳', `trend_ar` = 'مستقر', `note_en` = 'Hunters & Frankau has distributed Habanos since 1790. London\'s clubs — Davidoff of London among them — are world references.', `note_es` = 'Hunters & Frankau distribuye Habanos desde 1790. Los clubes londinenses, como Davidoff of London, son referencias mundiales.', `note_de` = 'Hunters & Frankau vertreibt Habanos seit 1790. Die Londoner Clubs, darunter Davidoff of London, sind Weltreferenzen.', `note_zh` = 'Hunters & Frankau 自 1790 年起经销哈瓦那雪茄。伦敦的会所（如 Davidoff of London）为世界标杆。', `note_ar` = 'هنترز آند فرانكاو توزّع الهابانوس منذ 1790. أندية لندن، ومنها دافيدوف لندن، مرجع عالمي.' WHERE `id` = 'uk_mkt';
UPDATE `markets` SET `consumption_en` = '$3.5B/year', `consumption_es` = '3.5 B$/año', `consumption_de` = '3.5 Mrd. $/Jahr', `consumption_zh` = '每年 3.5 十亿美元', `consumption_ar` = '3.5 مليار دولار/سنة', `cigars_en` = '~350M premium cigars/year', `cigars_es` = '~350 M de puros premium/año', `cigars_de` = 'ca. 350 Mio. Premium-Zigarren/Jahr', `cigars_zh` = '每年约 350 百万支优质雪茄', `cigars_ar` = '~350 مليون سيجار فاخر/سنة', `trend_en` = 'stable', `trend_es` = 'estable', `trend_de` = 'stabil', `trend_zh` = '平稳', `trend_ar` = 'مستقر', `note_en` = 'The world\'s largest market. The Cuban embargo since 1962 allows non-Cuban cigars only. Heartland of the specialist shop.', `note_es` = 'El mayor mercado del mundo. El embargo cubano desde 1962 solo permite puros no cubanos. Territorio de las tiendas especializadas.', `note_de` = 'Der größte Markt der Welt. Das Kuba-Embargo von 1962 lässt nur nicht-kubanische Zigarren zu. Kernland der Fachgeschäfte.', `note_zh` = '全球第一大市场。自 1962 年的古巴禁运只允许非古巴雪茄。专卖店文化的重镇。', `note_ar` = 'أكبر سوق في العالم. الحظر على كوبا منذ 1962 يسمح بغير الكوبي فقط. معقل المتاجر المتخصّصة.' WHERE `id` = 'usa_mkt';

