UPDATE `lounges` SET `description_en` = 'Founded in 2018. Sells Nicaraguan, Dominican and Cuban cigars, plus accessories.', `description_es` = 'Fundado en 2018. Venta de puros nicaragüenses, dominicanos y cubanos, y accesorios.', `description_de` = '2018 gegründet. Verkauf nicaraguanischer, dominikanischer und kubanischer Zigarren sowie Zubehör.', `description_zh` = '创立于 2018 年。经营尼加拉瓜、多米尼加与古巴雪茄及配件。', `description_ar` = 'تأسّس عام 2018. يبيع السيجار النيكاراغوي والدومينيكي والكوبي، إضافة إلى الملحقات.' WHERE `id` = '9';
